mapper.select:
LEFT JOIN (-- 找到各个会话中排名为1的数据 SELECT sender_id, receiver_id, shop_id, message_content, is_read, created_time, update_time, conversation_id, message_status, if_send_new_us FROM (-- 查询message表中的数据 根据conversation_id 并且按创建时间排序排名 SELECT sender_id, receiver_id, shop_id, message_content, is_read, created_time, update_time, conversation_id, message_status, ROW_NUMBER() OVER ( PARTITION BY conversation_id, shop_id ORDER BY created_time DESC ) AS row_num, if_send_new_us FROM kf_answers_message ) AS latest_messages -- 只查找排名为第一位的 WHERE row_num = 1 ) AS latest_message ON ( kf_answers_client.store_name = latest_message.shop_id AND ( CASE -- 如果sender_id为客服的话 那就拼接client_id=receiver_id WHEN latest_message.sender_id = '客服' THEN kf_answers_client.client_id = latest_message.receiver_id -- 如果sender_id不是客服，那就拼接client_id=sender_id ELSE kf_answers_client.client_id = latest_message.sender_id END ) ) LEFT JOIN (-- 获取每个客户最优订单 SELECT order_id, client_id, -- 明确指定client_id的来源表 order_status, ROW_NUMBER() OVER ( PARTITION BY client_id ORDER BY CASE order_status WHEN '纠纷中的订单' THEN 1 WHEN '等待您发货' THEN 2 WHEN '等待买家付款' THEN 3 WHEN '付款处理中' THEN 4 WHEN '等待买家收货' THEN 5 WHEN '订单关闭' THEN 6 WHEN '交易完成' THEN 7 ELSE 8 -- 默认为最后 END ) AS row_num FROM kf_answers_order ) AS latest_order ON kf_answers_client.client_id = latest_order.client_id AND latest_order.row_num = 1 -- 只返回每个客户的最优订单
and client_name like concat('%', #{clientName}, '%') and client_number like concat('%', #{clientNumber}, '%') and email like concat('%', #{email}, '%') and avatar_url = #{avatarUrl} and created_time = #{createdTime} and store_name = #{storeName} and is_read = #{isRead} and latest_message.sender_id != '客服' and message_status = #{messageStatus} and store_manager_name = #{storeManagerName}
ORDER BY created_time DESC -- 添加这一行按照创建时间降序排序，可按需修改为ASC（升序）

mapper.update:
update kf_answers_client
client_name = #{clientName}, client_number = #{clientNumber}, email = #{email}, avatar_url = #{avatarUrl}, created_time = #{createdTime}, update_time = #{updateTime}, create_by = #{createBy}, update_by = #{updateBy}, store_name = #{storeName}, custom_field_two = #{customFieldTwo},
where client_id = #{clientId}
